// Validate + stamp trace id. Auth already resolved company_id at the edge (header key → company mapping).
const b = $json.body ?? {};
const CHANNELS = ['voice','sms','facebook','instagram','google_business','email','web_chat','whatsapp'];

if (!b.company_id || !b.channel || !b.payload?.text || !b.payload?.from) {
  return [{ json: { _error: { code: 'invalid_input', message: 'company_id, channel, payload.from and payload.text are required', retryable: false } } }];
}
if (!CHANNELS.includes(b.channel)) {
  return [{ json: { _error: { code: 'unknown_channel', message: `channel must be one of ${CHANNELS.join(', ')}`, retryable: false } } }];
}

return [{ json: {
  company_id: b.company_id,
  request_id: b.request_id ?? crypto.randomUUID(),
  source: 'webhook',
  channel: b.channel,
  payload: { from: String(b.payload.from), text: String(b.payload.text), contact_hint: b.payload.contact_hint ?? null },
  started_at: Date.now(),
} }];

// Parse the agent's JSON contract; degrade gracefully to handoff on parse failure.
const base = $('Validate & Normalize').first().json;
let out;
try {
  const raw = $json.output ?? $json.text ?? '';
  out = typeof raw === 'string' ? JSON.parse(raw.replace(/^```json?\n?|```$/g, '').trim()) : raw;
} catch (e) {
  out = { reply: null, intent: 'other', actions: [], handoff: true, lead: { score_delta: 0, status_suggestion: null } };
}
return [{ json: { ...base, agent: out } }];
